function renderReturnFlights(total){$('returnFlights').innerHTML='<div class="flight-small"><p><b>11 月 14 日 · 20:00 后直飞候选</b></p><p>携程页面查询于 2026.10.29 20:29–20:32（北京时间），成人单程经济舱起价。下表为查询快照，不自动刷新价格；含税总价尚未核实，服务包、行李加购另计。</p><div class="flight-table"><table><thead><tr><th>航班</th><th>起飞 → 萧山到达</th><th>页面起价 / 人</th><th>香格里拉出发界限</th><th></th></tr></thead><tbody>'+returnFlights.map(f=>'<tr><td>'+f.code+'<br>'+f.airline+'</td><td>'+f.dep+' → '+(f.next?'11.15 ':'11.14 ')+f.arr+'<br>萧山 '+f.terminal+'</td><td class="price">¥'+f.price+' 起<br><small>'+f.bag+'</small></td><td>'+(total===null?'待车程':subtract(f.dep,total)+' 前')+'<br><small>按当前缓冲倒推</small></td><td><button class="outline use-flight" data-time="'+f.dep+'">用于试算</button></td></tr>').join('')+'</tbody></table></div><p>共享航班号没有重复当作独立飞机列出。21:30 与 22:30 起飞的航班均于 11 月 15 日凌晨到萧山，11 月 14 日当天无法落地。</p><a href="https://flights.ctrip.com/online/list/oneway-kmg-hgh?depdate=2026-11-14&cabin=y&adult=1&child=0&infant=0" target="_blank" rel="noopener">在携程重新查价 ↗</a></div>';$('returnFlights').querySelectorAll('.use-flight').forEach(b=>b.onclick=()=>{$('flightTime').value=b.dataset.time;saved.set('yn-flightTime',b.dataset.time);updateReturnEstimate()})}
async function resolvePoint(query,city){let key=query+'|'+city;if(points.has(key))return points.get(key);const p=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('百度地点检索超时')),18000);new BMapGL.Geocoder().getPoint(query,point=>{clearTimeout(timer);point?resolve(point):reject(Error('百度未找到地点：'+query))},city)});points.set(key,p);return p}
async function calculateRoute(id){if(pendingRoutes.has(id))return pendingRoutes.get(id);const job=(async()=>{const r=routes[id];try{const [from,to]=await Promise.all([resolvePoint(r.from,r.fc),resolvePoint(r.to,r.tc)]);const result=await new Promise((resolve,reject)=>{let done=false;const timer=setTimeout(()=>{if(!done){done=true;reject(Error('百度驾车查询超时，请重试'))}},25000);const driving=new BMapGL.DrivingRoute(map,{onSearchComplete(results){if(done)return;done=true;clearTimeout(timer);if(driving.getStatus()!==0||!results?.getPlan?.(0)){reject(Error('百度未返回可用驾车路线，请检查路线服务权限'));return}const plan=results.getPlan(0),seconds=plan.getDuration(false),meters=plan.getDistance(false);if(!(seconds>0&&meters>0)){reject(Error('百度车程数据无效'));return}const path=[];for(let n=0;n<plan.getNumRoutes();n++)path.push(...plan.getRoute(n).getPath());resolve({seconds,meters,path,from,to,start:r.from+(/[市]$/.test(r.from)?'（百度城市参考点，非酒店）':''),end:r.to+(/[市]$/.test(r.to)?'（百度城市参考点，非酒店）':''),queriedAt:new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date())})}});driving.search(from,to)});routeData[id]=result}catch(e){routeData[id]={error:e.message}}finally{pendingRoutes.delete(id);if(days[selected].routes?.includes(id))renderDriving()}})();pendingRoutes.set(id,job);return job}
