window.initBaiduMap=()=>{try{map=new BMapGL.Map('baiduMap');map.centerAndZoom(new BMapGL.Point(100.7,26.3),7);map.enableScrollWheelZoom(true);map.setTilt(55);map.setHeading(-12);$('mapEmpty').style.display='none';$('mapStatus').textContent='已连接 · 百度地图 GL';loadingMap=false;focusDay();for(const [id,v]of Object.entries(routeData))if(v.error)delete routeData[id];loadDayRoutes()}catch(e){mapError('地图初始化失败')}};
function loadMap(){if(!ak){mapError('等待 AK 配置');return}if(loadingMap||map)return;loadingMap=true;let s=document.createElement('script');s.src=`https://api.map.baidu.com/api?v=1.0&type=webgl&ak=${encodeURIComponent(ak)}&callback=initBaiduMap`;s.onerror=()=>mapError('地图资源加载失败');document.head.append(s);setTimeout(()=>{if(!map)mapError('地图未能完成加载')},25000)}
async function focusDay(){const token=++mapView;map.clearOverlays();map.setTilt(50);map.centerAndZoom(days[selected].city,11);for(const q of days[selected].places.filter(p=>!p.includes('萧山'))){try{const p=await resolvePoint(q,days[selected].city);if(token!==mapView)return;map.addOverlay(new BMapGL.Marker(p));map.addOverlay(new BMapGL.Label(q,{position:p,offset:new BMapGL.Size(12,-20)}))}catch{}}}
async function overview(){if(!map){toast('地图尚未连接');return}const token=++mapView;map.clearOverlays();let ps=[];for(const city of ['昆明市','大理市','丽江市','香格里拉市']){try{const p=await resolvePoint(city,city);if(token!==mapView)return;ps.push(p);map.addOverlay(new BMapGL.Marker(p));map.addOverlay(new BMapGL.Label(city,{position:p,offset:new BMapGL.Size(10,-20)}))}catch{}}if(ps.length>1){map.addOverlay(new BMapGL.Polyline([...ps,ps[0]],{strokeColor:'#285f4b',strokeWeight:3}));map.setViewport(ps)}$('mapStatus').textContent='全程顺序示意 · 查看单段可显示实际道路'}
$('overviewBtn').onclick=overview;$('tiltBtn').onclick=()=>{if(map)map.setTilt(map.getTilt()>0?0:60)};
function renderNotes(){const list=notesByDay[selected];$('notesList').innerHTML=list?list.length?list.map(n=>`<article class="shared-note"><div><b>${esc(n.author)}</b><time>${esc(new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date(n.createdAt)))}</time></div><p>${esc(n.text)}</p></article>`).join(''):'<p class="muted">这一天还没有共享备注。</p>':'<p class="muted">正在读取共享备注…</p>'}
async function loadNotes(){const day=selected,version=++notesRequest;try{const r=await fetch('/api/notes?day='+day,{cache:'no-store'});if(!r.ok)throw Error('无法连接共享备注服务');const data=await r.json();notesByDay[day]=data.notes;if(day===selected&&version===notesRequest){renderNotes();$('notesStatus').textContent='共享备注已同步'}}catch(e){if(day===selected&&version===notesRequest){$('notesStatus').textContent='共享备注服务暂不可用，请刷新重试。';if(!notesByDay[day])$('notesList').innerHTML=''}}}
$('noteAuthor').value=saved.get('yn-note-author');$('noteAuthor').oninput=e=>saved.set('yn-note-author',e.target.value);$('personalNote').oninput=e=>draftByDay[selected]=e.target.value;$('refreshNotes').onclick=loadNotes;
$('notesForm').onsubmit=async e=>{e.preventDefault();if(noteSubmitting)return;const author=$('noteAuthor').value.trim(),text=$('personalNote').value.trim(),day=selected;if(!author||!text){$('notesStatus').textContent='请填写署名和备注内容。';return}noteSubmitting=true;$('submitNote').disabled=true;$('notesStatus').textContent='正在发布…';try{const r=await fetch('/api/notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({author,text,day})});const body=await r.json();if(!r.ok)throw Error(body.error||'发布失败');draftByDay[day]='';saved.set('yn-note-author',author);if(day===selected){$('personalNote').value='';await loadNotes();$('notesStatus').textContent='已发布，其他访问者可查看。'}toast('备注已共享')}catch(err){$('notesStatus').textContent='未发布：'+err.message}finally{noteSubmitting=false;$('submitNote').disabled=false}};
setInterval(()=>{if(!document.hidden&&!noteSubmitting)loadNotes()},15000);

const weatherLocations=[...days.map((d,i)=>({...d,key:'day'+i,date:`2026-11-${String(i+8).padStart(2,'0')}`})),{key:'snow',lat:27.11,lng:100.18,date:'2026-11-11'},{key:'valley',lat:27.12,lng:100.23,date:'2026-11-12'}];
function weatherName(c){return c===0?'晴':c<=3?'多云':c<=48?'雾':c<=67?'有雨':c<=77?'降雪':c<=82?'阵雨':c<=86?'阵雪':'雷雨'}
function datum(key){let v=weatherData[key];return v&&v.low!=null&&v.high!=null&&v.code!=null?v:null}
function weatherBlock(v,label){if(!v)return `<div class="weather-detail">${label}：暂无该日有效预报</div>`;return `<div class="weather-detail">${label}：${Math.round(v.low)}–${Math.round(v.high)}°C · ${weatherName(v.code)}${v.rain==null?'':`<br>最大降水概率 ${v.rain}%`}</div>`}
function renderWeather(){const d=days[selected],v=datum('day'+selected);$('weather').innerHTML=`<p class="muted">11 月 ${8+selected} 日 · ${esc(d.city)}市区</p>${v?`<div class="weather-main">${Math.round(v.low)}° <span style="opacity:.4;font-size:21px">/</span> ${Math.round(v.high)}°</div><div class="weather-detail">${weatherName(v.code)}${v.rain==null?'':` · 最大降水概率 ${v.rain}%`}<br>当日数值预报 · 非实测</div>`:`<div class="weather-main" style="font-size:22px">${weatherState==='loading'?'正在获取…':weatherState==='error'?'天气暂不可用':'等待该日预报'}</div><div class="weather-detail">${weatherState==='error'?'天气接口未能成功返回，请稍后刷新。':'该日期暂无可用数据；不使用往年天气代替。'}</div>`}${selected===3?weatherBlock(datum('snow'),'雪山地区网格'):selected===4?weatherBlock(datum('valley'),'蓝月谷地区网格'):''}${weatherUpdated?`<p style="font-size:10px;color:#89957e">获取于 ${esc(weatherUpdated)}</p>`:''}<a href="https://www.weather.com.cn/yunnan/" target="_blank" rel="noopener" style="font-size:10px;text-decoration:underline">中国天气网复核 ↗</a>`}
async function loadWeather(){weatherState='loading';renderWeather();$('refreshWeather').disabled=true;try{const lat=weatherLocations.map(d=>d.lat).join(','),lng=weatherLocations.map(d=>d.lng).join(',');const url=`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lng}&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&forecast_days=16&timezone=Asia%2FShanghai`;const r=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error('Weather HTTP '+r.status);const response=await r.json();const data=Array.isArray(response)?response:[response];weatherData={};weatherLocations.forEach((d,i)=>{const daily=data[i]?.daily,n=daily?.time?.indexOf(d.date);if(n>=0)weatherData[d.key]={low:daily.temperature_2m_min?.[n],high:daily.temperature_2m_max?.[n],rain:daily.precipitation_probability_max?.[n],code:daily.weather_code?.[n]}});weatherState='ready';weatherUpdated=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date())}catch(err){weatherState='error';console.warn('Weather data unavailable',err.message)}finally{$('refreshWeather').disabled=false;renderWeather()}}
$('refreshWeather').onclick=loadWeather;

let dragStart;const scene=document.querySelector('.landscape');scene.addEventListener('pointerdown',e=>{if(e.target.closest('[data-day]'))return;dragStart={x:e.clientX,y:e.clientY};scene.setPointerCapture(e.pointerId)});scene.addEventListener('pointermove',e=>{if(dragStart){$('terrain').style.transform=`rotateX(${Math.max(5,Math.min(65,35+(e.clientY-dragStart.y)/6))}deg) rotateZ(${-7+(e.clientX-dragStart.x)/5}deg)`}});scene.addEventListener('pointerup',()=>dragStart=null);scene.addEventListener('pointercancel',()=>dragStart=null);document.querySelectorAll('[data-day]').forEach(el=>{const go=()=>{selectDay(Number(el.dataset.day));$('plan').scrollIntoView({behavior:'smooth'})};el.onclick=go;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}}});

$('printBtn').onclick=()=>{const timelineOriginal=$('timeline').innerHTML,driveOriginal=$('drivingPanel').innerHTML;$('drivingPanel').innerHTML='';$('timeline').innerHTML=days.map((d,i)=>`<section style="break-before:${i?'page':'auto'}"><h3>11.${i+8} · ${esc(d.title)}</h3><p>${esc(d.intro)}</p>${timeline(d)}${(d.routes||[]).map(routeCard).join('')}<p>${esc(d.note)}</p>${(notesByDay[i]||[]).map(n=>`<p>${esc(n.author)}：${esc(n.text)}</p>`).join('')}</section>`).join('');window.print();$('timeline').innerHTML=timelineOriginal;$('drivingPanel').innerHTML=driveOriginal;renderDriving()};
const initialHash=location.hash; const hash=location.hash.match(/^#day-([1-7])$/);selectDay(hash?Number(hash[1])-1:0);loadWeather();loadMap();



if(initialHash==='#preparation'){history.replaceState(null,'',initialHash);document.getElementById('preparation').scrollIntoView();}

